package cli

// Phase 1 prototype for issue #589: entity-level structural diffs in
// `entire explain`. This file is intentionally self-contained:
//   - Go entities via go/ast (stdlib).
//   - TypeScript / JavaScript entities via regex.
//   - Per-file local dependent count via regex.
//
// No tree-sitter / CGo dependency in this prototype. If the UX proves
// useful, a production version would graduate to tree-sitter (or shell
// out to inspect/sem) for proper multi-language coverage.

import (
	"context"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"path/filepath"
	"regexp"
	"sort"
	"strings"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// entity is a top-level declaration we know how to track across a diff.
// Signature is opaque text used only to detect "did the signature change"
// — its exact form is language-specific.
type entity struct {
	name      string
	signature string
	kind      string // "func", "method", "type", "const", "class"
}

type entityChange struct {
	kind       string // "added", "removed", "signature-changed", "modified"
	file       string
	name       string
	displayKind string
	before     string
	after      string
	dependents int
}

// renderEntityDiff returns the formatted Entities section for the given
// commits. Empty string if nothing useful was found (caller decides
// whether to omit the heading).
func renderEntityDiff(ctx context.Context, repo *git.Repository, commitSHAs []string, files []string) string {
	if repo == nil || len(commitSHAs) == 0 || len(files) == 0 {
		return ""
	}

	// For the prototype we union the diffs across all associated
	// commits. In practice there is usually exactly one.
	var changes []entityChange
	for _, sha := range commitSHAs {
		c, err := commitEntitiesDiff(ctx, repo, sha, files)
		if err != nil {
			continue
		}
		changes = append(changes, c...)
	}
	if len(changes) == 0 {
		return ""
	}

	return formatEntityChanges(changes)
}

func commitEntitiesDiff(_ context.Context, repo *git.Repository, sha string, files []string) ([]entityChange, error) {
	hash := plumbing.NewHash(sha)
	commit, err := repo.CommitObject(hash)
	if err != nil {
		return nil, err
	}

	var parent *object.Commit
	if commit.NumParents() > 0 {
		parent, _ = commit.Parent(0) //nolint:errcheck // best effort; nil parent means initial commit
	}

	var out []entityChange
	for _, f := range files {
		if !isSupportedExt(f) {
			continue
		}

		beforeBytes, _ := readFileAtCommit(parent, f) //nolint:errcheck // missing = added
		afterBytes, _ := readFileAtCommit(commit, f)  //nolint:errcheck // missing = removed

		beforeEnts := extractEntities(f, beforeBytes)
		afterEnts := extractEntities(f, afterBytes)

		out = append(out, diffEntities(f, beforeEnts, afterEnts, afterBytes)...)
	}
	return out, nil
}

func readFileAtCommit(commit *object.Commit, path string) ([]byte, error) {
	if commit == nil {
		return nil, nil
	}
	f, err := commit.File(path)
	if err != nil {
		return nil, err
	}
	r, err := f.Reader()
	if err != nil {
		return nil, err
	}
	defer r.Close() //nolint:errcheck
	var sb strings.Builder
	buf := make([]byte, 4096)
	for {
		n, err := r.Read(buf)
		if n > 0 {
			sb.Write(buf[:n])
		}
		if err != nil {
			break
		}
	}
	return []byte(sb.String()), nil
}

func isSupportedExt(path string) bool {
	switch strings.ToLower(filepath.Ext(path)) {
	case ".go", ".ts", ".tsx", ".js", ".jsx":
		return true
	}
	return false
}

func extractEntities(path string, content []byte) []entity {
	if len(content) == 0 {
		return nil
	}
	switch strings.ToLower(filepath.Ext(path)) {
	case ".go":
		return extractGoEntities(path, content)
	case ".ts", ".tsx", ".js", ".jsx":
		return extractTSEntities(content)
	}
	return nil
}

// --- Go ---------------------------------------------------------------

func extractGoEntities(path string, content []byte) []entity {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, content, parser.SkipObjectResolution)
	if err != nil {
		return nil
	}
	var ents []entity
	for _, decl := range f.Decls {
		switch d := decl.(type) {
		case *ast.FuncDecl:
			ents = append(ents, goFuncEntity(d, fset, content))
		case *ast.GenDecl:
			for _, spec := range d.Specs {
				switch s := spec.(type) {
				case *ast.TypeSpec:
					ents = append(ents, entity{
						name:      s.Name.Name,
						kind:      "type",
						signature: typeSignature(s, fset, content),
					})
				}
			}
		}
	}
	return ents
}

func goFuncEntity(d *ast.FuncDecl, fset *token.FileSet, content []byte) entity {
	name := d.Name.Name
	kind := "func"
	if d.Recv != nil && len(d.Recv.List) > 0 {
		kind = "method"
		recv := exprText(d.Recv.List[0].Type, fset, content)
		recv = strings.TrimPrefix(recv, "*")
		name = recv + "." + name
	}
	// Signature = "func (recv) name(params) results" — i.e., everything
	// up to the function body. Comparing this string is enough to
	// detect signature changes vs. body-only changes.
	sig := exprText(d.Type, fset, content)
	if d.Recv != nil {
		sig = "(" + exprText(d.Recv.List[0].Type, fset, content) + ") " + sig
	}
	return entity{name: name, kind: kind, signature: sig}
}

func typeSignature(s *ast.TypeSpec, fset *token.FileSet, content []byte) string {
	return exprText(s.Type, fset, content)
}

func exprText(node ast.Node, fset *token.FileSet, content []byte) string {
	if node == nil {
		return ""
	}
	pos := fset.Position(node.Pos())
	end := fset.Position(node.End())
	if pos.Offset < 0 || end.Offset > len(content) || end.Offset < pos.Offset {
		return ""
	}
	return strings.TrimSpace(string(content[pos.Offset:end.Offset]))
}

// --- TypeScript / JavaScript -----------------------------------------

// Best-effort regex extractors. Good enough for the prototype: catches
// top-level functions, arrow-function consts, and classes. Deliberately
// ignores nested declarations, JSX, and decorators — those are
// tree-sitter territory.

var (
	tsFuncRE  = regexp.MustCompile(`(?m)^\s*(?:export\s+)?(?:async\s+)?function\s+([A-Za-z_$][\w$]*)\s*(\([^)]*\))`)
	tsArrowRE = regexp.MustCompile(`(?m)^\s*(?:export\s+)?(?:const|let|var)\s+([A-Za-z_$][\w$]*)\s*[:=]\s*(?:async\s*)?(\([^)]*\))\s*=>`)
	tsClassRE = regexp.MustCompile(`(?m)^\s*(?:export\s+)?(?:abstract\s+)?class\s+([A-Za-z_$][\w$]*)`)
	tsConstRE = regexp.MustCompile(`(?m)^\s*export\s+const\s+([A-Za-z_$][\w$]*)\s*=`)
)

func extractTSEntities(content []byte) []entity {
	src := string(content)
	seen := map[string]bool{}
	var ents []entity

	for _, m := range tsFuncRE.FindAllStringSubmatch(src, -1) {
		name := m[1]
		if seen[name] {
			continue
		}
		seen[name] = true
		ents = append(ents, entity{name: name, kind: "func", signature: name + m[2]})
	}
	for _, m := range tsArrowRE.FindAllStringSubmatch(src, -1) {
		name := m[1]
		if seen[name] {
			continue
		}
		seen[name] = true
		ents = append(ents, entity{name: name, kind: "func", signature: name + m[2]})
	}
	for _, m := range tsClassRE.FindAllStringSubmatch(src, -1) {
		name := m[1]
		if seen[name] {
			continue
		}
		seen[name] = true
		ents = append(ents, entity{name: name, kind: "class", signature: name})
	}
	for _, m := range tsConstRE.FindAllStringSubmatch(src, -1) {
		name := m[1]
		if seen[name] {
			continue
		}
		seen[name] = true
		ents = append(ents, entity{name: name, kind: "const", signature: name})
	}
	return ents
}

// --- Diff -------------------------------------------------------------

func diffEntities(file string, before, after []entity, afterContent []byte) []entityChange {
	beforeMap := map[string]entity{}
	for _, e := range before {
		beforeMap[e.name] = e
	}
	afterMap := map[string]entity{}
	for _, e := range after {
		afterMap[e.name] = e
	}

	var changes []entityChange
	for name, b := range beforeMap {
		a, ok := afterMap[name]
		if !ok {
			changes = append(changes, entityChange{
				kind: "removed", file: file, name: name, displayKind: b.kind, before: b.signature,
			})
			continue
		}
		if a.signature != b.signature {
			changes = append(changes, entityChange{
				kind: "signature-changed", file: file, name: name, displayKind: a.kind,
				before: b.signature, after: a.signature,
				dependents: countLocalDependents(name, afterContent),
			})
		}
	}
	for name, a := range afterMap {
		if _, ok := beforeMap[name]; ok {
			continue
		}
		changes = append(changes, entityChange{
			kind: "added", file: file, name: name, displayKind: a.kind, after: a.signature,
			dependents: countLocalDependents(name, afterContent),
		})
	}

	sort.SliceStable(changes, func(i, j int) bool {
		if changes[i].file != changes[j].file {
			return changes[i].file < changes[j].file
		}
		return changes[i].name < changes[j].name
	})
	return changes
}

// countLocalDependents returns the number of call sites of name within
// the given source, excluding the declaration itself. Crude but useful
// at the file level — we count `name(` occurrences and subtract one for
// the definition.
func countLocalDependents(name string, content []byte) int {
	if name == "" || len(content) == 0 {
		return 0
	}
	// Strip method receiver if present ("Type.method" -> "method").
	short := name
	if i := strings.LastIndex(short, "."); i >= 0 {
		short = short[i+1:]
	}
	// Word boundary + open paren.
	re, err := regexp.Compile(`\b` + regexp.QuoteMeta(short) + `\s*\(`)
	if err != nil {
		return 0
	}
	matches := re.FindAllIndex(content, -1)
	n := len(matches) - 1 // subtract the declaration site
	if n < 0 {
		n = 0
	}
	return n
}

// --- Render -----------------------------------------------------------

func formatEntityChanges(changes []entityChange) string {
	var sb strings.Builder
	fmt.Fprintf(&sb, "Entities: (%d)\n", len(changes))

	currentFile := ""
	for _, c := range changes {
		if c.file != currentFile {
			fmt.Fprintf(&sb, "  %s\n", c.file)
			currentFile = c.file
		}
		marker := "?"
		switch c.kind {
		case "added":
			marker = "+"
		case "removed":
			marker = "-"
		case "signature-changed":
			marker = "~"
		case "modified":
			marker = "*"
		}
		dep := ""
		if c.dependents > 0 {
			plural := "s"
			if c.dependents == 1 {
