func diffEntities(file string, before, after []entity, afterContent []byte) []entityChange {
	type key struct{ name, kind string }
	beforeMap := map[key]entity{}
	for _, e := range before {
		beforeMap[key{e.name, e.kind}] = e
	}
	afterMap := map[key]entity{}
	for _, e := range after {
		afterMap[key{e.name, e.kind}] = e
	}

	var changes []entityChange
	for k, b := range beforeMap {
		a, ok := afterMap[k]
		if !ok {
			changes = append(changes, entityChange{
				kind: "removed", file: file, name: k.name, displayKind: b.kind, before: b.signature,
			})
			continue
		}
		if a.signature != b.signature {
			changes = append(changes, entityChange{
				kind: "signature-changed", file: file, name: k.name, displayKind: a.kind,
				before: b.signature, after: a.signature,
				dependents: dependentsFor(a, afterContent),
			})
		}
	}
	for k, a := range afterMap {
		if _, ok := beforeMap[k]; ok {
			continue
		}
		changes = append(changes, entityChange{
			kind: "added", file: file, name: k.name, displayKind: a.kind, after: a.signature,
			dependents: dependentsFor(a, afterContent),
		})
	}

	sort.SliceStable(changes, func(i, j int) bool {
		if changes[i].file != changes[j].file {
			return changes[i].file < changes[j].file
		}
		return changes[i].name < changes[j].name
	})
	return changes
}

// dependentsFor counts file-local call sites for entity kinds where
// "<name>(" is meaningful. For Convex routes, tables, and fields, the
// declaration is structural data, not a callable symbol — no count.
func dependentsFor(e entity, afterContent []byte) int {
	switch e.kind {
	case "route", "table", "field":
		return 0
	}
	return countLocalDependents(e.name, afterContent)
}

