package cli

import (
	"testing"
)

// entityNames extracts a stable []string of "kind name" pairs for assertions.
func entityNames(ents []entity) []string {
	out := make([]string, 0, len(ents))
	for _, e := range ents {
		out = append(out, e.kind+" "+e.name)
	}
	return out
}

func contains(haystack []string, needle string) bool {
	for _, s := range haystack {
		if s == needle {
			return true
		}
	}
	return false
}

func TestExtractGoEntities_FuncsAndTypes(t *testing.T) {
	t.Parallel()
	src := []byte(`package x

type Status struct {
	A int
}

func Foo(a int) error { return nil }

func (s *Status) Bar(b string) bool { return false }
`)
	ents := extractGoEntities("x.go", src)
	names := entityNames(ents)
	for _, want := range []string{"type Status", "func Foo", "method Status.Bar"} {
		if !contains(names, want) {
			t.Errorf("expected %q in %v", want, names)
		}
	}
}

func TestExtractGoEntities_SignatureChangeDetected(t *testing.T) {
	t.Parallel()
	before := []byte(`package x
func Foo(a int) error { return nil }
`)
	after := []byte(`package x
func Foo(a int, b string) error { return nil }
`)
	changes := diffEntities("x.go", extractGoEntities("x.go", before), extractGoEntities("x.go", after), after)
	if len(changes) != 1 {
		t.Fatalf("expected exactly one change, got %d: %+v", len(changes), changes)
	}
	if changes[0].kind != "signature-changed" || changes[0].name != "Foo" {
		t.Errorf("expected signature-changed for Foo, got %+v", changes[0])
	}
}

func TestExtractTSEntities_BasicFunctions(t *testing.T) {
	t.Parallel()
	src := []byte(`
export function getStatus(req: Request) { return null; }
const helper = (x: number) => x + 1;
class Widget {}
`)
	names := entityNames(extractTSEntities(src))
	for _, want := range []string{"func getStatus", "func helper", "class Widget"} {
		if !contains(names, want) {
			t.Errorf("expected %q in %v", want, names)
		}
	}
}

func TestExtractConvexEntities_Routes(t *testing.T) {
	t.Parallel()
	src := []byte(`
const http = httpRouter();
http.route({
  path: "/push",
  method: "POST",
  handler: someHandler
});
http.route({
  path: "/status",
  method: "GET",
  handler: otherHandler
});
`)
	names := entityNames(extractTSEntities(src))
	for _, want := range []string{"route POST /push", "route GET /status"} {
		if !contains(names, want) {
			t.Errorf("expected %q in %v", want, names)
		}
	}
}

func TestExtractConvexEntities_TablesAndFields(t *testing.T) {
	t.Parallel()
	src := []byte(`
export default defineSchema({
  syncEvents: defineTable({
    seq: v.number(),
    payload: v.object({ inner: v.string() })
  }),
  syncState: defineTable({
    name: v.string(),
    nextSeq: v.number(),
    activeLinkCount: v.optional(v.number())
  }).index("by_name", ["name"])
});
`)
	names := entityNames(extractTSEntities(src))
	wants := []string{
		"table syncEvents",
		"field syncEvents.seq",
		"field syncEvents.payload",
		"table syncState",
		"field syncState.name",
		"field syncState.nextSeq",
		"field syncState.activeLinkCount",
	}
	for _, want := range wants {
		if !contains(names, want) {
			t.Errorf("expected %q in %v", want, names)
		}
	}
	// Nested-object fields ("inner") must NOT bubble up to the table.
	if contains(names, "field syncEvents.inner") {
		t.Errorf("nested-object field leaked to top level: %v", names)
	}
}

func TestDiffEntities_AddedSchemaField(t *testing.T) {
	t.Parallel()
	before := []byte(`
export default defineSchema({
  syncState: defineTable({ name: v.string(), nextSeq: v.number() })
});
`)
	after := []byte(`
export default defineSchema({
  syncState: defineTable({ name: v.string(), nextSeq: v.number(), activeLinkCount: v.optional(v.number()) })
});
`)
	changes := diffEntities("schema.ts", extractTSEntities(before), extractTSEntities(after), after)
	var found bool
	for _, c := range changes {
		if c.kind == "added" && c.displayKind == "field" && c.name == "syncState.activeLinkCount" {
			found = true
		}
	}
	if !found {
		t.Errorf("expected added schema field syncState.activeLinkCount, got %+v", changes)
	}
}

func TestDiffEntities_FuncAndRouteSameNameDoNotConflate(t *testing.T) {
	t.Parallel()
	// Pathological case: a function and a route share the same string
	// "POST /push" — won't happen in practice (routes have spaces) but
	// the diff must key on (name, kind), not name alone.
	before := []entity{{name: "POST /push", kind: "route", signature: "POST /push"}}
	after := []entity{
		{name: "POST /push", kind: "route", signature: "POST /push"},
		{name: "POST /push", kind: "func", signature: "POST /push"},
	}
	changes := diffEntities("x.ts", before, after, nil)
	if len(changes) != 1 {
		t.Fatalf("expected one added func, got %d: %+v", len(changes), changes)
	}
	if changes[0].kind != "added" || changes[0].displayKind != "func" {
		t.Errorf("expected added func, got %+v", changes[0])
	}
}

func TestBalancedBraceBody_HandlesStringsAndNesting(t *testing.T) {
	t.Parallel()
	src := `prefix{a:"}",b:{c:1}}suffix`
	openPos := 6 // position of the outer '{'
	body, end, ok := balancedBraceBody(src, openPos)
	if !ok {
		t.Fatalf("balancedBraceBody returned !ok")
	}
	if body != `a:"}",b:{c:1}` {
		t.Errorf("body mismatch: got %q", body)
	}
	if src[end:] != "suffix" {
		t.Errorf("end mismatch: src[end:]=%q", src[end:])
	}
}

func TestStripNestedObjects(t *testing.T) {
	t.Parallel()
	in := `a: 1, b: { c: 2, d: 3 }, e: 4`
	out := stripNestedObjects(in)
	want := `a: 1, b: , e: 4`
	if out != want {
		t.Errorf("got %q want %q", out, want)
	}
}

