// extractConvexEntities augments the TS extractor with patterns specific
// to Convex backend code: HTTP route registrations and schema tables.
// These appear as nested call expressions, not top-level declarations.
func extractConvexEntities(src string, ents *[]entity) {
	// http.route({ path: "...", method: "..." })
	for _, openIdx := range convexRouteOpenRE.FindAllStringIndex(src, -1) {
		body, _, ok := balancedBraceBody(src, openIdx[1]-1)
