		}
		path := firstSubmatch(convexRoutePathRE, body)
		method := firstSubmatch(convexMethodRE, body)
		if path == "" || method == "" {
			continue
		}
		name := method + " " + path
		*ents = append(*ents, entity{name: name, kind: "route", signature: name})
	}

	// <table>: defineTable({ field: v.x, ... })
	for _, m := range convexTableOpenRE.FindAllStringSubmatchIndex(src, -1) {
		tableName := src[m[2]:m[3]]
		body, _, ok := balancedBraceBody(src, m[1]-1)
		if !ok {
			continue
		}
		*ents = append(*ents, entity{name: tableName, kind: "table", signature: tableName})

		// Top-level fields inside the table body. Strip nested object
		// bodies first so a `payload: v.object({inner: ...})` doesn't
		// leak `inner` as a top-level field.
		for _, fm := range convexFieldRE.FindAllStringSubmatch(stripNestedObjects(body), -1) {
			field := fm[1]
			fullName := tableName + "." + field
			*ents = append(*ents, entity{name: fullName, kind: "field", signature: fullName})
