// balancedBraceBody walks forward from a `{` and returns the body
// content (without the enclosing braces), the index *after* the closing
// `}`, and whether matching succeeded. String literals (single, double,
// and backtick) are honored so a `{` inside a string does not perturb
// depth.
func balancedBraceBody(src string, openPos int) (string, int, bool) {
	if openPos < 0 || openPos >= len(src) || src[openPos] != '{' {
		return "", -1, false
	}
	depth := 1
	i := openPos + 1
	var quote byte
	for i < len(src) && depth > 0 {
		c := src[i]
		if quote != 0 {
			if c == '\\' && i+1 < len(src) {
				i += 2
				continue
			}
			if c == quote {
				quote = 0
			}
			i++
			continue
		}
		switch c {
		case '"', '\'', '`':
			quote = c
		case '{':
			depth++
		case '}':
			depth--
		}
		i++
	}
	if depth != 0 {
		return "", -1, false
	}
	return src[openPos+1 : i-1], i, true
}

