// diff machinery must still key on (name, kind) — otherwise a future
// addition of a new entity kind could silently conflate with another.
func TestDiffEntities_KeyedOnNameAndKind(t *testing.T) {
	t.Parallel()
	before := []entity{{name: "Widget", kind: "class", signature: "Widget"}}
	after := []entity{
		{name: "Widget", kind: "class", signature: "Widget"},
		{name: "Widget", kind: "func", signature: "Widget()"},
	}
	changes := diffEntities("x.ts", before, after, nil)
	if len(changes) != 1 {
		t.Fatalf("expected one added func, got %d: %+v", len(changes), changes)
	}
	if changes[0].kind != entityChangeAdded || changes[0].displayKind != "func" {
		t.Errorf("expected added func, got %+v", changes[0])
	}
}

