22	var (
23		loadSummarySettings            = LoadEntireSettings
24		loadSummarySettingsFromFile    = settings.LoadFromFile
25		saveLocalSummarySettings       = SaveEntireSettingsLocal
26		getSummaryAgent                = agent.Get
27		listRegisteredAgents           = agent.List
28		isSummaryCLIAvailable          = agent.IsSummaryCLIAvailable
29		discoverSummaryProviders       = external.DiscoverAndRegister
30		discoverSummaryProvidersAlways = external.DiscoverAndRegisterAlways
