40	func resolveCheckpointSummaryProvider(ctx context.Context, w io.Writer) (*checkpointSummaryProvider, error) {
41		s, err := loadSummarySettings(ctx)
42		if err != nil {
43			return nil, fmt.Errorf("loading settings: %w", err)
44		}
45	
46		if s.SummaryGeneration != nil && s.SummaryGeneration.Provider != "" {
47			providerName := types.AgentName(s.SummaryGeneration.Provider)
48			discoverSummaryProviderIfMissing(ctx, providerName)
49			if err := ensureSummaryProviderPresent(ctx, providerName); err != nil {
50				return nil, err
51			}
52			return buildCheckpointSummaryProvider(providerName, s.SummaryGeneration.Model)
53		}
54	
55		// Use the always-variant so installed external plugins surface in the
56		// picker even when external_agents is currently off. Installation
57		// (placing entire-agent-* on $PATH) is the user's opt-in to "this
58		// plugin exists"; selecting it in the picker is when external_agents
59		// flips on (handled by persistSummaryProviderSelection).
60		discoverSummaryProvidersAlways(ctx)
61		candidates := listEnabledSummaryProviders(ctx)
62	
63		switch len(candidates) {
64		case 0:
65			return nil, errors.New("no summary-capable provider is available; install claude, codex, gemini, cursor, or copilot, install an external entire-agent-* plugin that declares text_generator, or set summary_generation.provider in settings")
66		case 1:
67			return autoSelectSummaryProvider(ctx, w, candidates[0].Name, "non-interactive auto-select: single installed provider")
68		default:
69			if !interactive.CanPromptInteractively() {
70				return autoSelectSummaryProvider(ctx, w, candidates[0].Name, "non-interactive auto-select: first detected of multiple")
71			}
72	
73			selected, err := promptForSummaryProvider(candidates)
74			if err != nil {
75				return nil, err
76			}
77			provider, err := autoSelectSummaryProvider(ctx, w, selected, "interactive prompt selection")
78			if err != nil {
79				return nil, err
80			}
81			fmt.Fprintf(w, "Using %s for summary generation.\n", provider.DisplayName)
82			return provider, nil
83		}
84	}
85	
86	func discoverSummaryProviderIfMissing(ctx context.Context, name types.AgentName) {
87		if _, err := getSummaryAgent(name); err == nil {
88			return
89		}
90		discoverSummaryProviders(ctx)
91	}
92	
93	// autoSelectSummaryProvider builds a provider for an auto-selected candidate
94	// (single-installed or non-interactive-first-of-many) and persists the choice
95	// so subsequent runs don't re-decide. Persistence failure is surfaced as a
96	// warning — not an error — because the selection is still usable in-process.
97	func autoSelectSummaryProvider(ctx context.Context, w io.Writer, name types.AgentName, reason string) (*checkpointSummaryProvider, error) {
98		logging.Info(ctx, reason, "provider", string(name))
99		provider, err := buildCheckpointSummaryProvider(name, "")
100		if err != nil {
101			return nil, err
102		}
103		flagFlipped, saveErr := persistSummaryProviderSelection(ctx, provider.Name, provider.Model)
104		if saveErr != nil {
105			logging.Warn(ctx, "failed to save summary provider selection, continuing without persistence",
106				"error", saveErr.Error())
107			fmt.Fprintf(w, "Warning: could not save provider selection: %v\nUse `entire configure --summarize-provider %s` to set it manually.\n", saveErr, provider.Name)
108		}
109		if flagFlipped {
110			fmt.Fprintln(w, externalAgentsAutoEnabledNotice)
111		}
112		return provider, nil
113	}
114	
115	func listEnabledSummaryProviders(_ context.Context) []checkpointSummaryProvider {
116		registered := listRegisteredAgents()
117		providers := make([]checkpointSummaryProvider, 0, len(registered))
118		for _, name := range registered {
119			ag, err := getSummaryAgent(name)
120			if err != nil {
121				continue
122			}
123			if _, ok := agent.AsTextGenerator(ag); !ok {
124				continue
125			}
126			// Check CLI binary on PATH for built-ins. External agents are already
127			// proven executable by discovery and are gated by text_generator.
128			if !isSummaryProviderAvailable(name, ag) {
129				continue
130			}
131			providers = append(providers, checkpointSummaryProvider{
132				Name:        name,
133				DisplayName: string(ag.Type()),
134			})
135		}
136		return providers
137	}
138	
139	func isSummaryProviderAvailable(name types.AgentName, ag agent.Agent) bool {
140		if external.IsExternal(ag) {
141			_, ok := agent.AsTextGenerator(ag)
142			return ok
143		}
144		return isSummaryCLIAvailable(name)
145	}
146	
147	func promptForSummaryProvider(providers []checkpointSummaryProvider) (types.AgentName, error) {
148		options := make([]huh.Option[string], 0, len(providers))
149		for _, provider := range providers {
150			options = append(options, huh.NewOption(provider.DisplayName, string(provider.Name)))
151		}
152	
153		var selected string
154		form := NewAccessibleForm(
155			huh.NewGroup(
156				huh.NewSelect[string]().
157					Title("Choose a summary provider").
158					Description("This choice will be saved. Use `entire configure` to change it later.").
159					Options(options...).
160					Value(&selected),
161			),
162		)
163		if err := form.Run(); err != nil {
164			return "", fmt.Errorf("summary provider selection cancelled: %w", err)
165		}
166	
167		return types.AgentName(selected), nil
168	}
