170	func buildCheckpointSummaryProvider(name types.AgentName, model string) (*checkpointSummaryProvider, error) {
171		ag, err := getSummaryAgent(name)
172		if err != nil {
173			return nil, fmt.Errorf("loading summary provider %s: %w", name, err)
174		}
175	
176		textGenerator, ok := agent.AsTextGenerator(ag)
177		if !ok {
178			return nil, fmt.Errorf("agent %s does not support summary generation", name)
179		}
180	
181		effectiveModel := summarize.ResolveModel(name, model)
182	
183		return &checkpointSummaryProvider{
184			Name:        name,
185			DisplayName: string(ag.Type()),
186			Model:       effectiveModel,
187			Generator: &summarize.TextGeneratorAdapter{
188				TextGenerator: textGenerator,
189				Model:         effectiveModel,
190			},
191		}, nil
192	}
193	
194	// ensureSummaryProviderPresent returns an error if the named summary provider's
195	// CLI binary is not on PATH. Checks the binary directly (via exec.LookPath)
196	// rather than DetectPresence, because DetectPresence checks repo-level agent
197	// configuration — a repo using Claude Code for development can still use Codex
198	// or Gemini for summary generation as long as the binary is installed.
199	func ensureSummaryProviderPresent(_ context.Context, name types.AgentName) error {
200		ag, err := getSummaryAgent(name)
201		if err != nil {
202			return fmt.Errorf("unknown summary provider %s: %w", name, err)
203		}
204		if _, ok := agent.AsTextGenerator(ag); !ok {
205			return fmt.Errorf("agent %s does not support summary generation", name)
206		}
207		if !isSummaryProviderAvailable(name, ag) {
208			return fmt.Errorf("summary provider %q is configured but its CLI binary is not on PATH; install it or update summary_generation.provider in settings", name)
209		}
210		return nil
211	}
212	
213	func validateSummaryProvider(provider string) error {
214		name := types.AgentName(provider)
215		ag, err := getSummaryAgent(name)
216		if err != nil {
217			return fmt.Errorf("unknown summary provider %q: %w", provider, err)
218		}
219		if _, ok := agent.AsTextGenerator(ag); !ok {
220			return fmt.Errorf("agent %q does not support summary generation", provider)
221		}
222		if !isSummaryProviderAvailable(name, ag) {
223			return fmt.Errorf("summary provider %q is configured but its CLI binary is not on PATH; install it or choose another provider", provider)
224		}
225		return nil
226	}
227	
228	// persistSummaryProviderSelection writes the chosen provider to
229	// settings.local.json. When the chosen provider is an external agent and
230	// external_agents is not yet enabled, it also flips that setting on so the
231	// plugin can actually run; in that case it returns flagFlipped=true so the
232	// caller can surface a one-time notice. The flag is written to local because
233	// the provider choice is already machine-specific (depends on $PATH).
234	func persistSummaryProviderSelection(ctx context.Context, provider types.AgentName, model string) (flagFlipped bool, err error) {
235		targetFileAbs, err := paths.AbsPath(ctx, settings.EntireSettingsLocalFile)
236		if err != nil {
237			targetFileAbs = settings.EntireSettingsLocalFile
238		}
239	
240		s, err := loadSummarySettingsFromFile(targetFileAbs)
241		if err != nil {
242			return false, fmt.Errorf("loading settings for update: %w", err)
243		}
244		if s.SummaryGeneration == nil {
245			s.SummaryGeneration = &settings.SummaryGenerationSettings{}
246		}
247		s.SummaryGeneration.SetProvider(string(provider), model)
248	
249		if ag, getErr := getSummaryAgent(provider); getErr == nil && external.IsExternal(ag) && !s.ExternalAgents {
250			s.ExternalAgents = true
251			flagFlipped = true
252		}
253	
254		if err := saveLocalSummarySettings(ctx, s); err != nil {
255			return false, fmt.Errorf("saving summary provider selection: %w", err)
256		}
257		return flagFlipped, nil
258	}
259	
260	func formatSummaryProviderDetails(provider *checkpointSummaryProvider) string {
261		if provider == nil {
262			return ""
263		}
264		displayModel := provider.Model
265		if displayModel == "" {
266			displayModel = "provider default"
267		}
268		var b strings.Builder
269		fmt.Fprintf(&b, "Provider: %s\n", provider.DisplayName)
270		fmt.Fprintf(&b, "Model: %s\n", displayModel)
271		return b.String()
272	}
