23	// GenerateFromTranscript generates a summary from pre-redacted transcript bytes.
24	// This is the shared implementation used by both explain --generate and auto-summarize.
25	//
26	// Parameters:
27	//   - ctx: context for cancellation
28	//   - transcriptBytes: pre-redacted transcript (JSONL or JSON format depending on agent)
29	//   - filesTouched: list of files modified during the session
30	//   - agentType: the agent type to determine transcript format
31	//   - generator: summary generator to use (if nil, uses default ClaudeGenerator)
32	//
33	// Returns nil, error if transcript is empty or cannot be parsed.
34	func GenerateFromTranscript(ctx context.Context, transcriptBytes redact.RedactedBytes, filesTouched []string, agentType types.AgentType, generator Generator) (*checkpoint.Summary, error) {
35		if transcriptBytes.Len() == 0 {
36			return nil, errors.New("empty transcript")
37		}
38	
39		// Build condensed transcript for summarization
40		condensed, err := BuildCondensedTranscriptFromBytes(transcriptBytes, agentType)
41		if err != nil {
42			return nil, fmt.Errorf("failed to parse transcript: %w", err)
43		}
44		if len(condensed) == 0 {
45			return nil, errors.New("transcript has no content to summarize")
46		}
47	
48		input := Input{
49			Transcript:   condensed,
50			FilesTouched: filesTouched,
51		}
52	
53		if generator == nil {
54			generator = &ClaudeGenerator{}
55		}
56	
57		summary, err := generator.Generate(ctx, input)
58		if err != nil {
59			return nil, err //nolint:wrapcheck // preserve *ClaudeError for errors.As at the explain layer
60		}
61	
62		return summary, nil
63	}
64	
65	// Generator generates checkpoint summaries using an LLM.
66	type Generator interface {
67		// Generate creates a summary from checkpoint data.
68		// Returns the generated summary or an error if generation fails.
69		Generate(ctx context.Context, input Input) (*checkpoint.Summary, error)
70	}
71	
72	// ResolveModel returns the effective model to use for summary generation.
73	// When the provider is Claude Code and no model is configured, it falls back
74	// to DefaultModel ("sonnet") — the summarize package's quality/cost choice,
75	// which differs from Claude Code's own invocation default ("haiku"). For
76	// other providers, an empty model means "use the provider CLI's own default",
77	// so we leave it unchanged.
78	func ResolveModel(name types.AgentName, model string) string {
79		if name == agent.AgentNameClaudeCode && model == "" {
80			return DefaultModel
81		}
82		return model
83	}
84	
85	// Input contains condensed checkpoint data for summarization.
86	type Input struct {
87		// Transcript is the condensed transcript entries
88		Transcript []Entry
89	
90		// FilesTouched are the files modified during the session
91		FilesTouched []string
92	}
93	
94	// EntryType represents the type of a transcript entry.
95	type EntryType string
96	
97	const (
98		// EntryTypeUser indicates a user prompt entry.
99		EntryTypeUser EntryType = "user"
100		// EntryTypeAssistant indicates an assistant response entry.
101		EntryTypeAssistant EntryType = "assistant"
102		// EntryTypeTool indicates a tool call entry.
103		EntryTypeTool EntryType = "tool"
104	)
105	
106	// Entry represents one item in the condensed transcript.
107	type Entry struct {
108		// Type is the entry type (user, assistant, tool)
109		Type EntryType
110	
111		// Content is the text content for user/assistant entries
112		Content string
113	
114		// ToolName is the name of the tool (for tool entries)
115		ToolName string
116	
117		// ToolDetail is a description or file path (for tool entries)
118		ToolDetail string
119	}
120	
121	// minimalDetailTools lists tools that should show only essential details in summaries.
122	// These tools often have verbose outputs that don't add value to summarization.
123	// The detail shown is typically just a path, URL, or identifier rather than full content.
124	var minimalDetailTools = map[string]bool{
125		"Skill":    true, // Show skill name only, not loaded content
126		"Read":     true, // Show file path only, not file contents
127		"WebFetch": true, // Show URL only, not fetched content
128	}
