130	// BuildCondensedTranscriptFromBytes parses pre-redacted transcript bytes and extracts a condensed view.
131	// This is a convenience function that combines parsing and condensing.
132	// The agentType parameter determines which parser to use (Claude/OpenCode JSONL vs Gemini JSON).
133	func BuildCondensedTranscriptFromBytes(content redact.RedactedBytes, agentType types.AgentType) ([]Entry, error) {
134		switch agentType {
135		case agent.AgentTypeGemini:
136			return buildCondensedTranscriptFromGemini(content)
137		case agent.AgentTypeFactoryAIDroid:
138			return buildCondensedTranscriptFromDroid(content)
139		case agent.AgentTypeOpenCode:
140			return buildCondensedTranscriptFromOpenCode(content)
141		case agent.AgentTypeCodex:
142			return buildCondensedTranscriptFromCodex(content)
143		case agent.AgentTypeClaudeCode, agent.AgentTypeCursor, agent.AgentTypeUnknown:
144			// Claude/cursor format - fall through to shared logic below
145		}
146		// Claude format (JSONL) - handles Claude Code, Unknown, and any future agent types
147		lines, err := transcript.ParseFromBytes(content.Bytes())
148		if err != nil {
149			if compactEntries, compactErr := buildCondensedTranscriptFromCompact(content); compactErr == nil {
150				return compactEntries, nil
151			}
152			return nil, fmt.Errorf("failed to parse transcript: %w", err)
153		}
154		entries := BuildCondensedTranscript(lines)
155		if len(entries) > 0 {
156			return entries, nil
157		}
158		if compactEntries, compactErr := buildCondensedTranscriptFromCompact(content); compactErr == nil {
159			return compactEntries, nil
160		}
161		return entries, nil
162	}
163	
164	func buildCondensedTranscriptFromCompact(redacted redact.RedactedBytes) ([]Entry, error) {
165		compactEntries, err := compact.BuildCondensedEntries(redacted.Bytes())
166		if err != nil {
167			return nil, fmt.Errorf("failed to parse compact transcript: %w", err)
168		}
169	
170		entries := make([]Entry, 0, len(compactEntries))
171		for _, entry := range compactEntries {
172			switch entry.Type {
173			case "user":
174				entries = append(entries, Entry{
175					Type:    EntryTypeUser,
176					Content: entry.Content,
177				})
178			case "assistant":
179				entries = append(entries, Entry{
180					Type:    EntryTypeAssistant,
181					Content: entry.Content,
182				})
183			case "tool":
184				entries = append(entries, Entry{
185					Type:       EntryTypeTool,
186					ToolName:   entry.ToolName,
187					ToolDetail: entry.ToolDetail,
188				})
189			}
190		}
191		return entries, nil
192	}
193	
194	// buildCondensedTranscriptFromGemini parses Gemini JSON transcript and extracts a condensed view.
195	func buildCondensedTranscriptFromGemini(redacted redact.RedactedBytes) ([]Entry, error) {
196		geminiTranscript, err := geminicli.ParseTranscript(redacted.Bytes())
197		if err != nil {
198			return nil, fmt.Errorf("failed to parse Gemini transcript: %w", err)
199		}
200	
201		var entries []Entry
202		for _, msg := range geminiTranscript.Messages {
203			switch msg.Type {
204			case geminicli.MessageTypeUser:
205				if msg.Content != "" {
206					entries = append(entries, Entry{
207						Type:    EntryTypeUser,
208						Content: msg.Content,
209					})
210				}
211			case geminicli.MessageTypeGemini:
212				// Add assistant content
213				if msg.Content != "" {
214					entries = append(entries, Entry{
215						Type:    EntryTypeAssistant,
216						Content: msg.Content,
217					})
218				}
219				// Add tool calls
220				for _, tc := range msg.ToolCalls {
221					entries = append(entries, Entry{
222						Type:       EntryTypeTool,
223						ToolName:   tc.Name,
224						ToolDetail: extractGenericToolDetail(tc.Args),
225					})
226				}
227			}
228		}
229	
230		return entries, nil
231	}
232	
233	// buildCondensedTranscriptFromOpenCode parses OpenCode export JSON transcript and extracts a condensed view.
234	func buildCondensedTranscriptFromOpenCode(redacted redact.RedactedBytes) ([]Entry, error) {
235		session, err := opencode.ParseExportSession(redacted.Bytes())
236		if err != nil {
237			return nil, fmt.Errorf("failed to parse OpenCode transcript: %w", err)
238		}
239		if session == nil {
240			return nil, nil
241		}
242	
243		var entries []Entry
244		for _, msg := range session.Messages {
245			switch msg.Info.Role {
246			case "user":
247				text := opencode.ExtractTextFromParts(msg.Parts)
248				if text != "" {
249					entries = append(entries, Entry{
250						Type:    EntryTypeUser,
251						Content: text,
252					})
253				}
254			case "assistant":
255				text := opencode.ExtractTextFromParts(msg.Parts)
256				if text != "" {
257					entries = append(entries, Entry{
258						Type:    EntryTypeAssistant,
259						Content: text,
260					})
261				}
262				for _, part := range msg.Parts {
263					if part.Type == "tool" && part.State != nil {
264						entries = append(entries, Entry{
265							Type:       EntryTypeTool,
266							ToolName:   part.Tool,
267							ToolDetail: extractOpenCodeToolDetail(part.State.Input),
268						})
269					}
270				}
271			}
272		}
273	
274		return entries, nil
275	}
