277	// buildCondensedTranscriptFromCodex converts Codex rollout JSONL into the compact
278	// transcript format, then reuses the shared transcript condensation logic.
279	func buildCondensedTranscriptFromCodex(content redact.RedactedBytes) ([]Entry, error) {
280		compacted, err := compact.Compact(content, compact.MetadataFields{
281			Agent:      "codex",
282			CLIVersion: "summarize",
283		})
284		if err != nil {
285			return nil, fmt.Errorf("failed to compact Codex transcript: %w", err)
286		}
