// renderEntityDiff returns the formatted Entities section for the given
// commits. Empty string if nothing useful was found (caller decides
// whether to omit the heading).
func renderEntityDiff(ctx context.Context, repo *git.Repository, commitSHAs []string, files []string) string {
	changes := computeEntityChanges(ctx, repo, commitSHAs, files)
	if len(changes) == 0 {
		return ""
	}
	return formatEntityChanges(changes)
}

// renderEntityDiffLines returns one preformatted fact line per entity
// change, suitable for inclusion in an LLM prompt as a flat list.
// Returns nil if there's nothing to report. The format is:
//
//	<file>: <verb> <kind> <name>[ (N local dependents)]
//
// e.g. "auth.go: signature changed func validate_token (3 local dependents)"
func renderEntityDiffLines(ctx context.Context, repo *git.Repository, commitSHAs, files []string) []string {
	changes := computeEntityChanges(ctx, repo, commitSHAs, files)
	if len(changes) == 0 {
		return nil
	}
	out := make([]string, 0, len(changes))
	for _, c := range changes {
		out = append(out, formatEntityChangeLine(c))
	}
	return out
}

// computeEntityChanges runs the per-file entity diff for the union of
// the given commits and returns the change set already sorted by
// (file, name).
func computeEntityChanges(ctx context.Context, repo *git.Repository, commitSHAs, files []string) []entityChange {
	if repo == nil || len(commitSHAs) == 0 || len(files) == 0 {
		return nil
	}
	var changes []entityChange
	for _, sha := range commitSHAs {
		c, err := commitEntitiesDiff(ctx, repo, sha, files)
		if err != nil {
			continue
		}
		changes = append(changes, c...)
	}
	return changes
}

func formatEntityChangeLine(c entityChange) string {
	verb := c.kind
	switch c.kind {
	case entityChangeSignatureChanged:
		verb = "signature changed"
	}
	dep := ""
	if c.dependents > 0 {
		plural := "s"
		if c.dependents == 1 {
			plural = ""
		}
		dep = fmt.Sprintf(" (%d local dependent%s)", c.dependents, plural)
	}
	return fmt.Sprintf("%s: %s %s %s%s", c.file, verb, c.displayKind, c.name, dep)
}

