// injectEntitiesSection inserts an "Entities:" block between the
// "Files:" listing and the "Transcript" section in the rendered
// checkpoint output. Returns output unchanged if there are no entity
// changes to show.
func injectEntitiesSection(ctx context.Context, output string, repo *git.Repository, commits []associatedCommit, files []string) string {
	if repo == nil || len(commits) == 0 || len(files) == 0 {
		return output
	}
	shas := make([]string, 0, len(commits))
	for _, c := range commits {
		shas = append(shas, c.SHA)
	}
	section := renderEntityDiff(ctx, repo, shas, files)
	if section == "" {
		return output
	}

