// line per (file, change) pair across the given commits — suitable for
// inclusion in an LLM prompt under [Entity Changes]. Returns nil when
// there's nothing to report or the inputs are insufficient.
func entityChangeLinesForCommits(ctx context.Context, repo *git.Repository, commits []associatedCommit, files []string) []string {
	if repo == nil || len(commits) == 0 || len(files) == 0 {
		return nil
	}
	shas := make([]string, 0, len(commits))
	for _, c := range commits {
		shas = append(shas, c.SHA)
	}
	return renderEntityDiffLines(ctx, repo, shas, files)
}

