package cli

// Project-wide dependent counting for Phase 2 of issue #589.
//
// Walks every tracked .go file at HEAD via go-git, parses each with
// go/ast, and records every call expression's target name. The result
// is a per-symbol map of (file -> call count) used to enrich the
// per-file local counts produced by diffEntities.
//
// Limitations called out for future phases:
//   - Go only; TS/JS callers stay on local-only counts.
//   - Name-based, not type-aware: callers of a same-named symbol in a
//     different package conflate. Counts are reported as "approximate"
//     in this regard. Resolving requires go/packages with type-checking.
//   - Generated and vendored code are skipped to avoid count distortion.
//   - No on-disk cache yet; the index is rebuilt on every explain. For
//     a 1k-file repo this is sub-second; larger repos will benefit from
//     a per-file blob-sha cache (deferred to Phase 3).

import (
	"context"
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"strings"

	"github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing/object"
)

// projectCallIndex maps a short symbol name to the list of (file, count)
// records observed across the repo. Lookup with Count subtracts the
// declaration site from the file the symbol is defined in.
type projectCallIndex struct {
	// bySymbol[name] = list of {file, count} pairs.
	bySymbol map[string][]callSite
}

type callSite struct {
	file  string
	count int
}

// buildProjectCallIndex walks every tracked .go file at HEAD and
// records every call expression. Returns a usable (possibly partial)
// index even when individual files fail to parse. Returns nil only
// when the repo HEAD itself can't be resolved.
func buildProjectCallIndex(_ context.Context, repo *git.Repository) (*projectCallIndex, error) {
	if repo == nil {
		return nil, fmt.Errorf("nil repo")
	}
	head, err := repo.Head()
	if err != nil {
		return nil, fmt.Errorf("head: %w", err)
	}
	commit, err := repo.CommitObject(head.Hash())
	if err != nil {
		return nil, fmt.Errorf("commit object: %w", err)
	}
	tree, err := commit.Tree()
	if err != nil {
		return nil, fmt.Errorf("commit tree: %w", err)
	}

	idx := &projectCallIndex{bySymbol: map[string][]callSite{}}

	// Walk every blob in the HEAD tree. ForEach errors are best-effort:
	// if a single file fails to parse we drop it from the index but
	// keep going.
	_ = tree.Files().ForEach(func(f *object.File) error { //nolint:errcheck // Best-effort
		if !shouldIndexFile(f.Name) {
			return nil
		}
		content, err := f.Contents()
		if err != nil {
			return nil
		}
		recordCallsInGoFile(idx, f.Name, []byte(content))
		return nil
	})

	return idx, nil
}

// shouldIndexFile decides whether a file path should contribute to the
// call index. Excludes vendored, generated, and non-Go files.
func shouldIndexFile(path string) bool {
	if !strings.HasSuffix(path, ".go") {
		return false
	}
	if strings.HasPrefix(path, "vendor/") || strings.Contains(path, "/vendor/") {
		return false
	}
	if strings.HasSuffix(path, ".pb.go") ||
		strings.HasSuffix(path, "_pb.go") ||
		strings.HasSuffix(path, ".gen.go") ||
		strings.HasSuffix(path, "_gen.go") ||
		strings.HasSuffix(path, "_generated.go") {
		return false
	}
	return true
}

// recordCallsInGoFile parses a Go source file and adds every call
// expression's target name to idx.bySymbol under the given path. Parse
// failures are silently skipped.
func recordCallsInGoFile(idx *projectCallIndex, path string, content []byte) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, content, parser.SkipObjectResolution)
	if err != nil {
		return
	}

	// First line check: skip files explicitly tagged as generated.
	if isGeneratedHeader(f) {
		return
	}

	// Per-file count first, then merge into the index. This keeps the
	// (path, count) records compact when a function is called many times
	// from one file.
	counts := map[string]int{}
	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		switch fn := call.Fun.(type) {
		case *ast.Ident:
			counts[fn.Name]++
		case *ast.SelectorExpr:
			counts[fn.Sel.Name]++
		}
		return true
	})

	for name, n := range counts {
		idx.bySymbol[name] = append(idx.bySymbol[name], callSite{file: path, count: n})
	}
}

// isGeneratedHeader returns true if the file's leading comments
// declare it as machine-generated. Matches the Go-tools convention:
// any line containing "Code generated" + "DO NOT EDIT" before the
// first non-comment token.
func isGeneratedHeader(f *ast.File) bool {
	for _, cg := range f.Comments {
		// Comments after the package decl don't count.
		if cg.Pos() > f.Package {
			break
		}
		for _, c := range cg.List {
			if strings.Contains(c.Text, "Code generated") && strings.Contains(c.Text, "DO NOT EDIT") {
				return true
			}
		}
	}
	return false
}

// Count returns the number of call sites of `name` across the repo,
// and the number of distinct files those call sites span. The
// declaration site in `definedInFile` (if any) is subtracted, so the
// result is a "callers" count, not a "mentions" count.
//
// Method names are normalized: "Type.Method" is queried as "Method"
// (Go selectors have no qualifier in the AST that's easy to match
// without type info).
func (idx *projectCallIndex) Count(name, definedInFile string) (total, fileCount int) {
	if idx == nil || name == "" {
		return 0, 0
	}
	short := name
	if i := strings.LastIndex(short, "."); i >= 0 {
		short = short[i+1:]
	}
	sites := idx.bySymbol[short]
	for _, s := range sites {
		c := s.count
		if s.file == definedInFile {
			c--
			if c < 0 {
				c = 0
			}
		}
		if c > 0 {
			total += c
			fileCount++
		}
	}
	return total, fileCount
}

// enrichWithProjectDependents replaces local-scope counts with
// project-wide counts for every Go entity in changes. TS/JS entities
// retain their local counts (different language; not in the index).
//
// Index construction is lazy: returns changes unmodified when no Go
// entities are present.
func enrichWithProjectDependents(ctx context.Context, repo *git.Repository, changes []entityChange) []entityChange {
	if repo == nil || len(changes) == 0 {
		return changes
	}
	if !hasGoChange(changes) {
		return changes
	}
	idx, err := buildProjectCallIndex(ctx, repo)
	if err != nil || idx == nil {
		return changes
	}
	for i := range changes {
		if !isGoChange(changes[i]) {
			continue
		}
		total, files := idx.Count(changes[i].name, changes[i].file)
		changes[i].dependents = total
		changes[i].dependentFiles = files
		changes[i].dependentScope = dependentScopeProject
	}
	return changes
}

func hasGoChange(changes []entityChange) bool {
	for _, c := range changes {
		if isGoChange(c) {
			return true
		}
	}
	return false
}

func isGoChange(c entityChange) bool {
	return strings.HasSuffix(c.file, ".go")
}

