func formatEntityChangeLine(c entityChange) string {
	verb := c.kind
	if c.kind == entityChangeSignatureChanged {
		verb = "signature changed"
	}
	return fmt.Sprintf("%s: %s %s %s%s", c.file, verb, c.displayKind, c.name, formatDependentSuffix(c))
}

// formatDependentSuffix returns the parenthesized dependent annotation
// for an entity change, or "" when there are no dependents to report.
// Project-scope counts include a "in M files" suffix so a 14-callers-
// across-6-files signature change is visually distinct from a 14-line
// local fan-out.
func formatDependentSuffix(c entityChange) string {
	if c.dependents <= 0 {
		return ""
	}
	depWord := "dependent"
	if c.dependents != 1 {
		depWord = "dependents"
	}
	switch c.dependentScope {
	case dependentScopeProject:
		fileWord := "file"
		if c.dependentFiles != 1 {
			fileWord = "files"
		}
		return fmt.Sprintf(" (%d %s in %d %s)", c.dependents, depWord, c.dependentFiles, fileWord)
	default:
		return fmt.Sprintf(" (%d local %s)", c.dependents, depWord)
	}
}

