package cli

import (
	"context"
	"path/filepath"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/testutil"
)

func TestShouldIndexFile(t *testing.T) {
	t.Parallel()
	cases := []struct {
		path string
		want bool
	}{
		{"main.go", true},
		{"internal/core/sync.go", true},
		{"main.py", false},
		{"vendor/github.com/foo/foo.go", false},
		{"vendor/foo.go", false},
		{"a/vendor/foo/foo.go", false},
		{"types.pb.go", false},
		{"types_pb.go", false},
		{"types.gen.go", false},
		{"types_gen.go", false},
		{"types_generated.go", false},
		{"README.md", false},
		{"main_test.go", true},
	}
	for _, c := range cases {
		if got := shouldIndexFile(c.path); got != c.want {
			t.Errorf("shouldIndexFile(%q) = %v, want %v", c.path, got, c.want)
		}
	}
}

func TestRecordCallsInGoFile_CountsCallExprs(t *testing.T) {
	t.Parallel()
	src := []byte(`package x

func A() {}
func B() {
	A()
	A()
	C()
}
func C() {}
`)
	idx := &projectCallIndex{bySymbol: map[string][]callSite{}}
	recordCallsInGoFile(idx, "x.go", src)

	if got := len(idx.bySymbol["A"]); got != 1 {
		t.Errorf("A: got %d sites, want 1", got)
	}
	if got := idx.bySymbol["A"][0].count; got != 2 {
		t.Errorf("A.count: got %d, want 2", got)
	}
	if got := idx.bySymbol["C"][0].count; got != 1 {
		t.Errorf("C.count: got %d, want 1", got)
	}
	// FuncDecls themselves are not counted — only CallExprs.
	if got := idx.bySymbol["B"]; len(got) != 0 {
		t.Errorf("B: got %v call sites, want 0 (FuncDecl, never called)", got)
	}
}

func TestRecordCallsInGoFile_SelectorCalls(t *testing.T) {
	t.Parallel()
	src := []byte(`package x
import "fmt"
func F() {
	fmt.Println("hi")
	fmt.Println("hello")
	x.Foo()
}
`)
	idx := &projectCallIndex{bySymbol: map[string][]callSite{}}
	recordCallsInGoFile(idx, "x.go", src)

	if got := idx.bySymbol["Println"][0].count; got != 2 {
		t.Errorf("Println: got %d, want 2", got)
	}
	if got := idx.bySymbol["Foo"][0].count; got != 1 {
		t.Errorf("Foo: got %d, want 1", got)
	}
}

func TestRecordCallsInGoFile_SkipsGenerated(t *testing.T) {
	t.Parallel()
	src := []byte(`// Code generated by mockery. DO NOT EDIT.
package x
func F() { ManyCalls() }
`)
	idx := &projectCallIndex{bySymbol: map[string][]callSite{}}
	recordCallsInGoFile(idx, "x.go", src)
	if len(idx.bySymbol) != 0 {
		t.Errorf("expected empty index for generated file, got %d entries", len(idx.bySymbol))
	}
}

func TestRecordCallsInGoFile_BadSyntaxIsIgnored(t *testing.T) {
	t.Parallel()
	idx := &projectCallIndex{bySymbol: map[string][]callSite{}}
	recordCallsInGoFile(idx, "x.go", []byte("this is not go"))
	if len(idx.bySymbol) != 0 {
		t.Errorf("expected empty index for bad source, got %v", idx.bySymbol)
	}
}

func TestProjectCallIndex_Count(t *testing.T) {
	t.Parallel()
	idx := &projectCallIndex{bySymbol: map[string][]callSite{
		"Foo": {{file: "a.go", count: 2}, {file: "b.go", count: 1}},
		"Bar": {{file: "a.go", count: 0}}, // synthetic edge case
	}}

	total, files := idx.Count("Foo")
	if total != 3 || files != 2 {
		t.Errorf("Count(Foo) = (%d, %d); want (3, 2)", total, files)
	}

	// Method-style name normalizes to short name.
	idx.bySymbol["Bar"] = []callSite{{file: "a.go", count: 5}}
	total, files = idx.Count("Type.Bar")
	if total != 5 || files != 1 {
		t.Errorf("Count(Type.Bar) = (%d, %d); want (5, 1)", total, files)
	}

	total, files = idx.Count("Missing")
	if total != 0 || files != 0 {
		t.Errorf("Count(Missing) = (%d, %d); want (0, 0)", total, files)
	}
}

func TestEnrichWithProjectDependents_GoOnly(t *testing.T) {
	t.Parallel()
	// Construct a synthetic repo: a.go defines Foo and is called from
	// b.go and c.go. Then enrichWithProjectDependents is invoked on a
	// changes set that says Foo was added in a.go — we expect the
	// project count to override the local count.
	tmp := t.TempDir()
	testutil.InitRepo(t, tmp)
	testutil.WriteFile(t, tmp, "a.go", `package x
func Foo() {}
`)
	testutil.WriteFile(t, tmp, "b.go", `package x
func B() { Foo() }
`)
	testutil.WriteFile(t, tmp, "c.go", `package x
func C() { Foo(); Foo() }
`)
	// Also a non-Go file and a generated file — both must be ignored.
	testutil.WriteFile(t, tmp, "d.ts", `function helper() { Foo(); }`)
	testutil.WriteFile(t, tmp, "e.go", `// Code generated by tool. DO NOT EDIT.
package x
func E() { Foo(); Foo(); Foo() }
`)
	testutil.GitAdd(t, tmp, ".")
	testutil.GitCommit(t, tmp, "initial")

	repo := testutil.OpenRepo(t, tmp)
	changes := []entityChange{
		{kind: entityChangeAdded, file: "a.go", name: "Foo", displayKind: "func", dependents: 0, dependentScope: dependentScopeLocal},
		{kind: entityChangeAdded, file: "d.ts", name: "helper", displayKind: "func", dependents: 0, dependentScope: dependentScopeLocal},
	}

	enriched := enrichWithProjectDependents(context.Background(), repo, changes)
	if len(enriched) != 2 {
		t.Fatalf("expected 2 changes, got %d", len(enriched))
	}

	// Foo: 3 call sites total (1 in b.go, 2 in c.go), 2 distinct files.
	// e.go is generated and excluded; d.ts is not Go and excluded.
	got := enriched[0]
	if got.dependentScope != dependentScopeProject {
		t.Errorf("Foo.scope: got %q, want %q", got.dependentScope, dependentScopeProject)
	}
	if got.dependents != 3 {
		t.Errorf("Foo.dependents: got %d, want 3", got.dependents)
	}
	if got.dependentFiles != 2 {
		t.Errorf("Foo.dependentFiles: got %d, want 2", got.dependentFiles)
	}

	// TS entity left untouched.
	got = enriched[1]
	if got.dependentScope != dependentScopeLocal {
		t.Errorf("helper.scope: got %q, want %q (TS should keep local scope)", got.dependentScope, dependentScopeLocal)
	}
}

func TestEnrichWithProjectDependents_NoGoChangesSkipsIndex(t *testing.T) {
	t.Parallel()
	// When no Go entities are present, enrichment must short-circuit
	// without ever calling buildProjectCallIndex (which would be
	// wasteful work for TS-only diffs).
	changes := []entityChange{
		{kind: entityChangeAdded, file: "a.ts", name: "foo", displayKind: "func", dependents: 2, dependentScope: dependentScopeLocal},
	}
	enriched := enrichWithProjectDependents(context.Background(), nil, changes)
	if enriched[0].dependentScope != dependentScopeLocal {
		t.Errorf("expected scope to remain local for TS-only diff, got %q", enriched[0].dependentScope)
	}
	if enriched[0].dependents != 2 {
		t.Errorf("expected dependents preserved, got %d", enriched[0].dependents)
	}
}

func TestFormatDependentSuffix_ProjectWide(t *testing.T) {
	t.Parallel()
	cases := []struct {
		name string
		c    entityChange
		want string
	}{
		{"local-singular", entityChange{dependents: 1, dependentScope: dependentScopeLocal}, " (1 local dependent)"},
		{"local-plural", entityChange{dependents: 3, dependentScope: dependentScopeLocal}, " (3 local dependents)"},
		{"project-singular", entityChange{dependents: 1, dependentFiles: 1, dependentScope: dependentScopeProject}, " (1 dependent in 1 file)"},
		{"project-multi", entityChange{dependents: 14, dependentFiles: 6, dependentScope: dependentScopeProject}, " (14 dependents in 6 files)"},
		{"zero", entityChange{dependents: 0}, ""},
	}
	for _, c := range cases {
		if got := formatDependentSuffix(c.c); got != c.want {
			t.Errorf("%s: got %q, want %q", c.name, got, c.want)
		}
	}
}

