// recordCallsInGoFile parses a Go source file and adds every call
// expression's target name to idx.bySymbol under the given path. Parse
// failures are silently skipped.
func recordCallsInGoFile(idx *projectCallIndex, path string, content []byte) {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, content, parser.SkipObjectResolution)
	if err != nil {
		return
	}

	// First line check: skip files explicitly tagged as generated.
	if isGeneratedHeader(f) {
		return
	}

	// Per-file count first, then merge into the index. This keeps the
	// (path, count) records compact when a function is called many times
	// from one file.
	counts := map[string]int{}
	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		switch fn := call.Fun.(type) {
		case *ast.Ident:
			counts[fn.Name]++
		case *ast.SelectorExpr:
			counts[fn.Sel.Name]++
		}
		return true
	})

	for name, n := range counts {
		idx.bySymbol[name] = append(idx.bySymbol[name], callSite{file: path, count: n})
	}
}

// isGeneratedHeader returns true if the file's leading comments
// declare it as machine-generated. Matches the Go-tools convention:
// any line containing "Code generated" + "DO NOT EDIT" before the
// first non-comment token.
func isGeneratedHeader(f *ast.File) bool {
	for _, cg := range f.Comments {
		// Comments after the package decl don't count.
		if cg.Pos() > f.Package {
			break
		}
		for _, c := range cg.List {
			if strings.Contains(c.Text, "Code generated") && strings.Contains(c.Text, "DO NOT EDIT") {
				return true
			}
		}
	}
	return false
}

