// recordCallsInGoFile parses a Go source file and adds every call
// expression's target name to idx.bySymbol under the given path. Parse
// failures are silently skipped.
func recordCallsInGoFile(idx *projectCallIndex, path string, content []byte) {
	if hasGeneratedHeader(content) {
		return
	}

	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, path, content, parser.SkipObjectResolution)
	if err != nil {
		return
	}

	// Per-file count first, then merge into the index. This keeps the
	// (path, count) records compact when a function is called many times
	// from one file.
	counts := map[string]int{}
	ast.Inspect(f, func(n ast.Node) bool {
		call, ok := n.(*ast.CallExpr)
		if !ok {
			return true
		}
		switch fn := call.Fun.(type) {
		case *ast.Ident:
			counts[fn.Name]++
		case *ast.SelectorExpr:
			counts[fn.Sel.Name]++
		}
		return true
	})

	for name, n := range counts {
		idx.bySymbol[name] = append(idx.bySymbol[name], callSite{file: path, count: n})
	}
}

// hasGeneratedHeader returns true if the file's leading comments
// declare it as machine-generated. Matches the Go-tools convention:
// any line containing "Code generated" + "DO NOT EDIT" before the
// "package" keyword.
//
// Implemented as a byte scan rather than going through the AST so we
// can short-circuit before parsing — generated files tend to be huge
// (e.g. mockery, protobuf, _generated.go) and parsing them all the way
// would dominate index-build time on monorepos.
func hasGeneratedHeader(content []byte) bool {
	// Scan only the file header — once we've seen "package", the
	// generated marker (if any) was supposed to appear before it.
	limit := len(content)
	if pkg := indexBytes(content, []byte("\npackage ")); pkg >= 0 {
		limit = pkg
	} else if pkg := indexBytes(content, []byte("package ")); pkg >= 0 && pkg < 8 {
		limit = pkg
	}
	if limit > 4096 {
		limit = 4096
	}
	header := content[:limit]
	return indexBytes(header, []byte("Code generated")) >= 0 &&
		indexBytes(header, []byte("DO NOT EDIT")) >= 0
}

func indexBytes(haystack, needle []byte) int {
	return bytesIndex(haystack, needle)
}

